"""Human review of universal transition code, scoped calibration and fresh truth."""
import json
from html import escape
from app.core.v10.timing_calibration import fit_onset_delays
from scripts.yellow_video_review import OUT,ROOT
from scripts.cardinal_clock_link import read,save,sha


def main():
    metrics=read(OUT/'evaluation.json');models=read(OUT/'comparison_models.json');onsets={}
    # Reproduce the already frozen first-window delays through the head-generic
    # training API. Never choose new parameters after the fresh evaluation.
    old=read(ROOT/'evidence/learned_archive_integration_20261018/archive_1/result.json')['estimated_signals']
    calibration=read(OUT/'frozen_recipe.json')['calibration']['profiles'][0]['calibration']
    off=(1740632395000-old['schedule_base_timestamp_ms'])/1000+calibration['clock_delta_s']
    train=[]
    for color,file in [('GREEN','video_only_truth_sealed.json'),('RED','video_red_truth_sealed.json')]:
        windows=read(ROOT/'evidence/direct_video_truth_20261018/sverdlovsky'/file)['windows']
        for row in next(w for w in windows if w['window']=='calibration')['transitions']:
            train.append(dict(color=color,bracket_s=[t+off for t in row['bracket_s']]))
    fitted=fit_onset_delays(old,train,approach='N',training_range_s=[900+off,1500+off],
        clock_provenance={'independent_vehicle_link_supported':True,'evidence':'clock3600/result.json',
            'delta_s':calibration['clock_delta_s'],'uncertainty':'conditional fixed-geometry link'})
    for color,value in fitted['onset_bias_s'].items():assert abs(value-calibration['onset_bias_s'][color])<1e-9
    training_receipt=dict(result=fitted,exact_frozen_delays_reproduced=True,
        purpose='post-evaluation training-only reproduction; deployed parameters were frozen earlier, unchanged',
        fresh_validation_labels_received=False)
    if (OUT/'generic_training_reproduction.json').exists():assert read(OUT/'generic_training_reproduction.json')==training_receipt
    else:save(OUT/'generic_training_reproduction.json',training_receipt)
    for site in ['sverdlovsky','enthusiasts']:
        result=read(OUT/('integration_'+site)/'result.json');est=result['estimated_signals']
        assert est['available'] and est['transition_timing']
        if site=='sverdlovsky':
            previous=read(ROOT/'evidence/learned_archive_integration_20261018/archive_1/result.json')['schedule']
            for key in ['raw_hsmm_segments','baseline_segments','phase_count','period_s']:assert result['schedule'][key]==previous[key]
            assert est['segments']==models['models']['calibrated_with_transitions']['segments']
            assert est['transition_timing']['phase_boundary_calibration']
        else:assert est['transition_timing']['phase_boundary_calibration'] is None
        onsets[site]=dict(available=True,heads=list(est['topology']),states=sorted({h['main']['state'] for s in est['states'] for h in s['heads'].values()}),
            source_member=result['input_scope']['source_member'],source_sha_scoped_bias=bool(est['transition_timing']['phase_boundary_calibration']))
    save(OUT/'integration_receipt.json',dict(status='PASS',real_archives=onsets,
        predictions_use_no_annotations=True,raw_learned_phase_boundaries_unchanged=True,
        display_phase_name_order='exported model uses C/A/B instead of prior wrapper A/B/C; same indices, boundaries and mapped operating signals'))
    payload=dict(models=models,truth={site:read(OUT/site/'fresh_truth_sealed.json')['rows'] for site in ['sverdlovsky','enthusiasts']})
    page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Видео и сигналы с жёлтым</title><style>body{font:17px/1.5 system-ui;max-width:1250px;margin:24px auto;padding:0 14px;background:#111720;color:#edf4ff}a{color:#9ccdff}button,select,input{font:inherit;margin:6px;padding:8px}video{width:100%;max-height:60vh;background:#000}.cards{display:flex;gap:12px;flex-wrap:wrap}.card{background:#253047;padding:15px;min-width:170px;flex:1}canvas{width:360px;max-width:100%;image-rendering:pixelated}strong{font-size:25px}.GREEN{color:#49d17d}.YELLOW,.RED_YELLOW{color:#ffcf60}.RED{color:#ff7185}.UNKNOWN{color:#a9b7c7}</style><h1>Жёлтый и исправленная задержка: сверка с видео</h1><p>Выберите перекрёсток и соответствующий исходный MP4. Видео читается локально. Свердловский: основной N и три цикла нового контрольного участка. Энтузиастов: видимая голова E, видеометки; прогноз к часам видео пока не привязан.</p><select id="site"><option value="sverdlovsky">Свердловский — N</option><option value="enthusiasts">Энтузиастов — E</option></select><input id="file" type="file" accept="video/mp4"><p id="status">Выберите MP4</p><video id="video" controls></video><p id="pts">—</p><div class="cards"><div class="card"><canvas id="zoom" width="360" height="260"></canvas></div><div class="card">Прежний прогноз<br><strong id="old">UNKNOWN</strong></div><div class="card">С переходами и поправкой<br><strong id="new">UNKNOWN</strong></div></div><button id="green">Показать зелёный</button><button id="yellow">Показать жёлтый</button><button id="red">Показать красный</button><button id="back">−0,1 с</button><button id="next">+0,1 с</button><p>Жёлтый — 3 с; красный с жёлтым — 2 с как явно принятое допущение, которое можно отключить в модели. Наблюдаемые лампы других голов этим не подтверждены. На Энтузиастов кнопки показывают только видеометки; UNKNOWN означает отсутствие принятой связи часов.</p><p><a href="report.html">Результаты, ограничения и готовое приложение</a></p><script>const DATA=__DATA__,v=document.getElementById('video'),ctx=document.getElementById('zoom').getContext('2d');ctx.imageSmoothingEnabled=false;let url=null,loadedSite=null;const el=id=>document.getElementById(id);function stateAt(t,name){if(el('site').value!=='sverdlovsky')return 'UNKNOWN';const m=DATA.models.models[name],u=t-DATA.models.video_offset_s;let a=0,b=m.segments.length;while(a<b){const mid=(a+b)>>1;if(m.segments[mid][0]<=u)a=mid+1;else b=mid;}const r=m.segments[a-1];return r&&u<r[1]?m.states[r[2]].heads.N.main.state:'UNKNOWN'}function render(t){el('pts').textContent='PTS '+t.toFixed(6)+' с';for(const [id,key] of [['old','original_binary'],['new','calibrated_with_transitions']]){const s=loadedSite===el('site').value?stateAt(t,key):'UNKNOWN';el(id).textContent=s;el(id).className=s}if(v.readyState>=2){const box=loadedSite==='sverdlovsky'?[1940,864,180,120]:[390,650,120,130];ctx.clearRect(0,0,360,260);ctx.drawImage(v,...box,0,0,360,260)}}function frame(n,m){render(m.mediaTime);v.requestVideoFrameCallback(frame)}if(v.requestVideoFrameCallback)v.requestVideoFrameCallback(frame);v.onseeked=()=>render(v.currentTime);v.ontimeupdate=()=>render(v.currentTime);el('file').onchange=e=>{const f=e.target.files[0];if(!f)return;const expected=el('site').value==='sverdlovsky'?3089546077:6792283598;if(f.size!==expected){el('status').textContent='Размер файла не совпадает с проверенным MP4';return}if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(f);loadedSite=el('site').value;v.src=url;el('status').textContent='Локальное видео '+loadedSite};el('site').onchange=()=>{v.pause();render(v.currentTime);el('status').textContent='Выберите MP4 для нового перекрёстка'};function seek(t){if(!v.src||loadedSite!==el('site').value)return;v.pause();v.currentTime=Math.max(0,t)}for(const [id,color] of [['green','GREEN'],['yellow','YELLOW'],['red','RED']])el(id).onclick=()=>{const r=DATA.truth[el('site').value].find(r=>r.color===color&&r.index===1);seek(r.bracket_s[1]+.4)};el('back').onclick=()=>seek(v.currentTime-.1);el('next').onclick=()=>seek(v.currentTime+.1);window.__YELLOW_REVIEW__={stateAt,seek,DATA};</script></html>'''
    page=page.replace('__DATA__',json.dumps(payload,ensure_ascii=False).replace('</','<\\/'))
    with (OUT/'video_comparison.html').open('x',encoding='utf8',newline='\n') as f:f.write(page)
    before=metrics['results']['original_binary'];after=metrics['results']['calibrated_with_transitions'];table=''
    for color in ['GREEN','YELLOW','RED']:
        a=before['onsets'][color]['mean_absolute_midpoint_error_s'];b=after['onsets'][color]['mean_absolute_midpoint_error_s']
        table+=f'<tr><td>{color}</td><td>{"не моделировался" if a is None else f"{a:.3f} с"}</td><td>{b:.3f} с</td><td>3/3</td></tr>'
    report='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Traffic Phase — жёлтый и точность</title><style>body{font:17px/1.55 system-ui;background:#111720;color:#edf4ff;max-width:1150px;margin:30px auto;padding:0 16px}a{color:#9ccdff}li{margin:8px 0}table{border-collapse:collapse;width:100%}th,td{border:1px solid #53637c;padding:9px}.scroll{overflow:auto}img{max-width:100%}.note{padding:16px;background:#302917}</style><h1>Жёлтый добавлен в алгоритм и приложение</h1><p>В общем расчёте временной истории появились YELLOW и RED_YELLOW: данные JSON, HTML, курсор и выгрузка используют одну историю. Переходы строятся для каждой основной головы по непрерывным участкам; основной зелёный не прерывается жёлтым при смене стрелки. Допсекции остаются GREEN/OFF. На пропусках и противоречиво коротких участках нет выдуманного цвета.</p><ul><li><a href="integration_sverdlovsky/viewer.html">Открыть готовое приложение: Свердловский, реальный архив</a></li><li><a href="integration_enthusiasts/viewer.html">Открыть готовое приложение: Энтузиастов, реальный архив, основные E/W</a></li><li><a href="video_comparison.html">Выбрать MP4 и сравнить светофор с прогнозом до/после</a></li></ul><p>Для нового анализа перезапустите START_WEB.cmd из audit_checkout и откройте /visualization/learned. Выберите перекрёсток и загрузите исходный ZIP/JSON. Калибровка задержки Свердловского применяется только к точному SHA256 обученного источника; другой день получает общую модель переходов без этой численной поправки.</p><h2>Что требует норматив</h2><p><a href="https://protect.gost.ru/gost/details/94160176-3252-4e7d-8534-2d172e6aa0de">Росстандарт: действующий ГОСТ Р52289-2019</a>, <a href="https://www.mos.ru/upload/documents/files/6980/GOSTR52289-2019TehnicheskiesredstvaorganizaciidorojnogodvijeniyaP_.pdf">п.7.5.2 в тексте на mos.ru</a>: основной жёлтый3с, красный с жёлтым не более2с; возможен режим без красного с жёлтым и предусмотрено исключение для старых контроллеров. Модель принимает2с как явное допущение, допускает0с. Зелёное мигание и мерцание LED на камере не объявляются жёлтым.</p><h2>Новая проверка по видео3300–3600с</h2><p>Параметры зафиксированы до просмотра этого участка. Размечены9 включений Свердловского (3 зелёных,3 жёлтых,3 красных) и8 Энтузиастов (3 зелёных,2 жёлтых,3 красных). Сомнительные интервалы расширены, третий жёлтый Энтузиастов не размечен. Красно-жёлтый onset независимо не проверен, это остаётся нормативной гипотезой.</p><p>Дополнительная пятая машина у конца часа Свердловского подтвердила прежний сдвиг часов1,253838с без подгонки по лампам; максимум ошибки10,96px при50px допуске. Условный диапазон1,127–1,369с зависит от геометрии и ручных точек и не является сертификатом аппаратных часов.</p><div class="scroll"><table><tr><th>Включение N main</th><th>MAE до</th><th>MAE после</th><th>В пределах0,5с от видеоинтервала</th></tr>'''+table+'''</table></div><p>На уверенных внутренних интервалах этих трёх циклов ошибка состояния сократилась с25,88 до0,48с из275,17 оцениваемых секунд. Границы, их неопределённость и неразмеченные красно-жёлтые участки в эту долю не включены. Один лишь нормативный жёлтый без исправления задержки не улучшил эту метрику:25,88с.</p><p class="note">Это проверка одной видимой основной головы на новом временном участке той же записи. Не является99,8% точностью всего алгоритма, независимым днём или проверкой всех стрелок/голов. MAE приведены по серединам интервалов кадров при фиксированном сдвиге часов; физическая погрешность устройства сюда не включена. Для Энтузиастов ошибка JSON↔видео не вычислена: часы офлайн-экспорта ещё не привязаны.</p><h2>Что универсально</h2><p>Код переходов и обучение отдельных задержек включения зелёного/красного не содержат названия перекрёстка или фиксированного запаздывания. Любая голова может быть обучена по своим clock-linked меткам первой части записи. Наблюдаемые потоки могут продолжаться на жёлтый или стоять при уступании: такие события не превращаются автоматически в GREEN/RED. Числа2,644/3,685с относятся к конкретно проверенной модели и источнику; совместное смещение границы фазы удерживает согласованность основных голов, но время остальных голов ещё не проверено отдельно.</p><p>Полный набор1392 tests PASS, затем28 затронутых проверок PASS после добавления общего API обучения. Два реальных ZIP обработаны без разметки при прогнозе. Сырые логические фазы по потокам сохранены; улучшена оценка сигналов и их временных переходов. Новая калибровка не заявляет автоматическое определение числа фаз.</p><p><a href="evaluation.json">Полные метрики</a> · <a href="sverdlovsky/fresh_truth_sealed.json">Свежая разметка Свердловского</a> · <a href="enthusiasts/fresh_truth_sealed.json">Свежая разметка Энтузиастов</a> · <a href="generic_training_reproduction.json">Общий метод воспроизводит замороженную поправку</a> · <a href="integration_receipt.json">Проверка реальных архивов</a></p><details><summary>Исходные пиксели новых видеометок</summary><img src="sverdlovsky/fresh_endpoints.png"><img src="enthusiasts/fresh_endpoints.png"><p>Первый предложенный before жёлтого Энтузиастов был исправлен на предыдущий фактический зелёный кадр3367.866667с перед окончательной фиксацией; исходное предложение сохранено.</p></details></html>'''
    with (OUT/'report.html').open('x',encoding='utf8',newline='\n') as f:f.write(report)
    print('PASS: exact frozen training reproduced; real integrations match; report and MP4 review built')


if __name__=='__main__':main()
